function manage(){const rows=[...materials];return shell(`${heading('Материалы','Добавление, подготовка и публикация общей библиотеки.',btn('Добавить материал','plus','primary'))}<div class="row between mb24"><div class="row gap8"><div class="input search-wide placeholder">${ic('search','tiny')}Найти материал</div>${btn('Все типы','down')}${btn('Любой статус','down')}</div><span class="small muted">8 материалов</span></div><div class="table-wrap"><table class="manage-table"><thead><tr><th style="width:40px"><span class="checkbox"></span></th><th>Материал</th><th>Тип</th><th>Источник</th><th>Подготовка</th><th>Видимость</th><th></th></tr></thead><tbody>${rows.map((m,i)=>`<tr><td><span class="checkbox"></span></td><td><div class="material-title">${m.title}</div><div class="sub">/library/${m.slug}</div></td><td>${m.type}</td><td>${m.format==='RUTUBE'?'Rutube':m.format==='TECHHELPER'?'TechHelper':'Файл · '+m.format}</td><td>${badge(i===2?'Слайды готовятся':'Готово',i===2?'amber':'green')}</td><td>${i===2?badge('Скрыт'):badge('Опубликован','outline')}</td><td>${square('more')}</td></tr>`).join('')}</tbody></table><div class="table-foot"><span>Показаны 8 из 8 материалов</span><span>Сортировка: новые первыми</span></div></div><div class="footer-note">Один материал может входить в несколько подборок. Изменения карточки доступны только редактору.</div>`,{admin:true,active:'Материалы',path:'Материалы'})}
function editMaterial(){return shell(`${heading('Регламент согласования','Карточка материала · DOCX · Локальный файл',`${btn('Посмотреть','eye')}${btn('Сохранить','check','primary')}`)}<div class="form-columns"><div><div class="panel stack">${field('Название','Регламент согласования')}${field('Постоянный адрес','/library/reglament-soglasovaniya','При смене адреса старый продолжит перенаправлять сюда.')}${field('Описание','Правила подготовки, согласования и публикации документов команды.','', 'widearea')}<div class="grid2">${field('Автор / источник','Команда DreamDocs')}${field('Теги','Документы · Процессы')}</div></div><div class="panel"><h3>Обложка</h3><div class="cover-edit mt16">${art(materials[5],true)}<div>${btn('Заменить изображение','upload')}<p class="small muted mt8">Или использовать обложку по типу материала.</p></div></div></div><div class="panel"><div class="row between"><h3>Файл и версии</h3>${btn('Загрузить новую версию','upload')}</div><div class="version-row mt16"><div>Версия 2 · Регламент.docx<div class="small muted mt8">11 ноября 2026 · 2,4 МБ</div></div>${badge('Текущая','green')}</div><div class="version-row"><span>Версия 1 · 8 ноября 2026</span><span class="muted small">Предыдущая</span></div><span class="small muted">Новый файл сохраняет карточку и её постоянную ссылку.</span></div></div><aside><div class="panel"><h3>Видимость</h3><div class="row between mt16"><span class="small">Опубликован</span><span class="toggle"></span></div><p class="small muted mt16" style="line-height:1.7">Доступен читателям библиотеки.</p></div><div class="panel"><h3>Подборки</h3><div class="checkline"><span class="checkbox checked">✓</span>Начните с DreamDocs</div><div class="checkline"><span class="checkbox checked">✓</span>Документы без хаоса</div><div class="checkline"><span class="checkbox"></span>Знания внутри команды</div></div><div class="panel"><h3>Представления</h3><div class="row between mt16"><span class="small">Документ</span>${badge('Готов','green')}</div><div class="row between mt16"><span class="small">Текст и скорочтение</span>${ic('check','tiny')}</div></div></aside></div>`,{admin:true,active:'Материалы',path:'Карточка материала',compact:true})}
function editCollection(){return shell(`${heading('Начните с DreamDocs','Состав, порядок и оформление подборки.',`${btn('Посмотреть','eye')}${btn('Сохранить','check','primary')}`)}<div class="form-columns"><div><div class="panel"><div class="grid2">${field('Название подборки','Начните с DreamDocs')}${field('Адрес','/collections/start-v-dreamdocs')}</div><div class="mt16">${field('Описание','Материалы для знакомства с продуктом и основными рабочими сценариями.','', 'widearea')}</div></div><div class="panel"><div class="row between"><h3>Материалы · 6</h3>${btn('Добавить из библиотеки','plus')}</div><p class="small muted mt8">Перетаскивайте строки, чтобы изменить порядок.</p>${[materials[3],materials[2],materials[1],materials[4],materials[5],materials[7]].map((m,i)=>listRow(m,i,true)).join('')}</div></div><aside><div class="panel"><h3>Видимость</h3><div class="row between mt16"><span class="small">Опубликована</span><span class="toggle"></span></div></div><div class="panel"><h3>Обложка подборки</h3><div class="collection-art mt16" style="height:150px;border-radius:8px;padding:19px"><div class="art-kicker">ПОДБОРКА</div><b style="font-size:24px">Начните<br>с DreamDocs</b></div><div class="mt16">${btn('Заменить обложку','upload')}</div></div>${notice('Удаление строки убирает материал из этой подборки. Сам материал остаётся в библиотеке.')}</aside></div>`,{admin:true,active:'Состав подборок',path:'Состав подборки',compact:true})}
function sourcesPage(){return shell(`${heading('Источники','Подключения для получения опубликованных материалов.')}<div class="form-columns"><div><div class="panel"><div class="row between"><h2>DreamAgent / TechHelper</h2>${btn('Добавить адрес','plus')}</div><p class="small muted mt8">Только разрешённые серверы для подключения шеринговых ссылок.</p><div class="source-row mt16"><div><h3>techhelper.example.org</h3><p>Документы, статьи БЗ и публичные записи</p></div><div class="row">${badge('Проверено','green')}${square('more')}</div></div><div class="mt16">${notice('Административный токен источника не требуется: используются доступные по ссылке опубликованные материалы.')}</div></div><div class="panel"><h2>Другие шеринги и видео</h2>${[['Buildin','Публичные страницы и связанные ссылки'],['Rutube · YouTube · VK Видео','Ссылки на отдельные ролики'],['Прямые медиаадреса','Воспроизведение, если источник разрешает']].map(x=>`<div class="source-row"><div><h3>${x[0]}</h3><p>${x[1]}</p></div>${badge('Подключён','outline')}</div>`).join('')}</div><div class="panel"><h2>Правило обновления</h2><p class="small muted mt16" style="line-height:1.8">Документы и статьи открываются из сохранённой публикации. Новое содержимое получаем по действию редактора «Обновить из источника».</p><div class="mt16">${notice('Если источник закроет доступ, предупредим перед завершением обновления. Автоматического удаления сохранённой версии нет.')}</div></div></div><aside><div class="panel"><h3>Обработка файлов</h3><div class="source-row"><div><h3 style="font-size:13px">Word и презентации</h3><p>Подготовка представлений</p></div>${badge('Доступна','green')}</div><div class="source-row"><div><h3 style="font-size:13px">Извлечение текста</h3><p>PDF с текстовым слоем</p></div>${ic('check','tiny')}</div><p class="small muted mt16" style="line-height:1.8">Распознавание сканов и автоматическая расшифровка медиа не подключены.</p></div><div class="panel"><h3>Новый источник</h3><p class="small muted mt8" style="line-height:1.8">Провайдеры добавляются после проверки их ссылок и возможностей отображения.</p></div></aside></div>`,{admin:true,active:'Источники',path:'Источники'})}
function login(){return `<div class="login"><div class="login-art">${brand()}<h1>Знания собраны.<br>Осталось открыть.</h1><p>Книги, документы, презентации и медиа в общей библиотеке. Один материал — для всех ваших продуктов.</p><div class="label">Общая библиотека DreamDocs</div></div><div class="login-form"><div class="state-icon" style="margin:0 0 24px">${ic('lock')}</div><h1>Вход редактора</h1><p>Для добавления материалов и управления библиотекой.</p>${field('Почта','editor@example.org')}${field('Пароль','••••••••••••')}${btn('Войти','arrow','primary big')}<div class="divider"></div><div style="text-align:center">${btn('Вернуться в библиотеку','arrow','ghost')}</div><p style="font-size:12px;margin-top:33px">Доступ к управлению выдаёт администратор библиотеки.</p></div></div>`}
function preparationError(){return shell(`${heading('Подготовка презентации','Исходный файл сохранён, представление пока не готово.',btn('К материалам','arrow'))}<div class="grid2" style="grid-template-columns:minmax(0,1fr) 365px"><div class="panel" style="padding:35px"><div class="row gap24">${mini(materials[2])}<div><h2>DreamDocs: от документа к процессу</h2><p class="small muted mt8">PPTX · 8,6 МБ · Добавлен 11 ноября 2026</p></div></div><div class="divider"></div>${notice('Не удалось подготовить слайды. Материал не опубликован как готовый к просмотру.','error')}<div class="row between mt24"><span>Исходный файл</span>${badge('Сохранён','green')}</div><div class="row between mt24"><span>Слайды</span>${badge('Ошибка подготовки','red')}</div><div class="row between mt24"><span>Текст</span>${badge('Не извлечён')}</div><div class="divider"></div><p class="muted small" style="line-height:1.8">Попробуйте обработать файл ещё раз или загрузить исправленную версию. Карточка и её адрес останутся прежними.</p><div class="row mt24 gap8">${btn('Повторить обработку','refresh','primary')}${btn('Заменить файл','upload')}</div></div><div class="panel" style="height:max-content"><h3>Карточка сохранена</h3><p class="muted small mt16" style="line-height:1.8">/library/dreamdocs-ot-dokumenta-k-processu</p><div class="divider"></div>${badge('Скрыт до готовности')}<p class="muted small mt16" style="line-height:1.8">Состояния файла, слайдов и текста учитываются отдельно.</p></div></div>`,{admin:true,active:'Материалы',path:'Подготовка файла'})}
function mobileCatalogue(){return `<div class="mobile"><header class="mobile-top">${brand()}${square('menu')}</header><main class="mobile-content"><h1>Библиотека</h1><p class="small muted mt8">Книги, документы и медиа</p><div class="input placeholder">${ic('search','tiny')}Название, автор или тег</div><div class="filter-row">${['Все','Книги','Документы','Видео'].map((x,i)=>`<div class="pill ${i===0?'active':''}">${x}</div>`).join('')}${square('settings')}</div><div class="row between small muted" style="margin:17px 0 13px"><span>8 материалов</span><span>Сначала новые ${ic('down','tiny')}</span></div><div class="cards">${[materials[0],materials[1],materials[2],materials[3]].map(card).join('')}</div></main><nav class="mobile-nav"><div class="active">${ic('grid')}Каталог</div><div>${ic('folder')}Подборки</div><div>${ic('lock')}Вход редактора</div></nav></div>`}
